function Assert-True([bool]$Condition, [string]$Message) { if (-not $Condition) { throw "Assertion failed: $Message" } }
function Pump-Ui([int]$Milliseconds) { $frame=New-Object Windows.Threading.DispatcherFrame; $timer=New-Object Windows.Threading.DispatcherTimer; $timer.Interval=[TimeSpan]::FromMilliseconds($Milliseconds); $timer.Add_Tick({$timer.Stop();$frame.Continue=$false});$timer.Start();[Windows.Threading.Dispatcher]::PushFrame($frame) }
function Wait-UiTask($Task,[int]$TimeoutMilliseconds=30000){$watch=[Diagnostics.Stopwatch]::StartNew();while(-not $Task.IsCompleted-and$watch.ElapsedMilliseconds-lt$TimeoutMilliseconds){Pump-Ui 20};Assert-True $Task.IsCompleted "Async operation timed out.";if($Task.IsFaulted){throw $Task.Exception.Flatten().InnerExceptions[0]};$Task.GetAwaiter().GetResult()|Out-Null}
function Write-TestImage([string]$Path){$bitmap=[Drawing.Bitmap]::new(160,100);$graphics=[Drawing.Graphics]::FromImage($bitmap);try{$graphics.Clear([Drawing.Color]::FromArgb(18,28,44));$brush=[Drawing.SolidBrush]::new([Drawing.Color]::White);try{$graphics.FillRectangle($brush,24,18,92,58)}finally{$brush.Dispose()};$bitmap.Save($Path,[Drawing.Imaging.ImageFormat]::Png)}finally{$graphics.Dispose();$bitmap.Dispose()}}
function New-RectangleContour(){[HalconDotNet.HObject]$value=$null;[HalconDotNet.HOperatorSet]::GenContourPolygonXld([ref]$value,[HalconDotNet.HTuple]@([double]0,0,40,40,0),[HalconDotNet.HTuple]@([double]0,80,80,0,0));$value}
function New-OpenContour(){[HalconDotNet.HObject]$value=$null;[HalconDotNet.HOperatorSet]::GenContourPolygonXld([ref]$value,[HalconDotNet.HTuple]@([double]8,15,24,36),[HalconDotNet.HTuple]@([double]4,18,35,52));$value}

$tempRoot=Join-Path ([IO.Path]::GetTempPath()) ('halcon-vm-s42-'+[Guid]::NewGuid().ToString('N'));[IO.Directory]::CreateDirectory($tempRoot)|Out-Null
$imagePath=Join-Path $tempRoot 'production.png';Write-TestImage $imagePath
$mainType=$assembly.GetType('HalconWinFormsDemo.MainWindow',$true);$recipeServiceType=$assembly.GetType('HalconWinFormsDemo.Services.RecipeService',$true);$loggerType=$assembly.GetType('HalconWinFormsDemo.Services.AppLogger',$true);$kindType=$assembly.GetType('HalconWinFormsDemo.Models.VmToolKind',$true);$metadataType=$assembly.GetType('HalconWinFormsDemo.Models.ToolMetadata',$true);$snapshotType=$assembly.GetType('HalconWinFormsDemo.Models.VmXldSnapshot',$true)
$private=[Reflection.BindingFlags]'Instance,NonPublic';$all=[Reflection.BindingFlags]'Instance,NonPublic,Public';$staticPublic=[Reflection.BindingFlags]'Static,Public'
$args=New-Object 'object[]' 1;$args[0]=$tempRoot.ToString();$service=$recipeServiceType.GetConstructor([Type[]]@([string])).Invoke($args);$logger=$loggerType.GetConstructor([Type[]]@([string])).Invoke($args);$window=$mainType.GetConstructor($private,$null,[Type[]]@($recipeServiceType,$loggerType),$null).Invoke([object[]]@($service,$logger))
function Field([string]$Name){$field=$mainType.GetField($Name,$all);if($null-eq$field){throw "Field missing: $Name"};$field.GetValue($window)}
function Set-Private([string]$Name,$Value){$mainType.GetField($Name,$private).SetValue($window,$Value)}
$flow=$mainType.GetField('flowTools',$private).GetValue($window);$catalog=$mainType.GetField('toolCatalog',$private).GetValue($window);$create=$mainType.GetMethod('CreateFlowTool',$private);$execute=$mainType.GetMethod('ExecuteFlowTool',$private);$disposeFlow=$mainType.GetMethod('DisposeFlowTools',$private);$runProjective=$mainType.GetMethod('RunXldProjectiveTransformTool',$private);$captureRecipe=$mainType.GetMethod('CaptureRecipe',$private);$setProduction=$mainType.GetMethod('SetProductionRunMode',$private);$refreshProduction=$mainType.GetMethod('RefreshProductionRunView',$private);$runRange=$mainType.GetMethod('RunInspectionRangeAsync',$private);$loadQueue=$mainType.GetMethods($private)|Where-Object{$_.Name-eq'LoadImageQueue'-and$_.GetParameters().Count-eq1}|Select-Object -First 1
function New-Tool([string]$Kind,[string]$Name){$create.Invoke($window,[object[]]@([Enum]::Parse($kindType,$Kind),$Name,$true,$null))}
function Invoke-Projective($Tool,$Xld){try{$runProjective.Invoke($window,[object[]]@($Tool,$Xld))} catch [Reflection.TargetInvocationException]{throw $_.Exception.InnerException}}
function Invoke-Execute($Tool,[string]$Source){try{$execute.Invoke($window,[object[]]@($Tool,$Source))} catch [Reflection.TargetInvocationException]{throw $_.Exception.InnerException}}
function Get-Out($Tool,[string]$Port){$value=$null;if(-not$Tool.TryGetOutputValue($Port,[ref]$value)){throw "$($Tool.InstanceName).$Port missing"};$value}
function New-Snapshot($Xld,$Tool){$snapshotType.GetMethod('Create',$staticPublic).Invoke($null,[object[]]@($Xld,$Tool.ToolId,$Tool.InstanceName,'XLD'))}

foreach($name in @('MainMenu','DeveloperToolbarPanel','ProductionToolbarPanel','ToolCatalogPanel','FlowWorkspacePanel','ImageWorkspacePanel','ImageWorkspaceToolbarPanel','ProductionRunPanel','ProductionSchemeText','ProductionOverallResultText','ProductionOkText','ProductionNgText','ProductionYieldText','ProductionCycleText','ProductionCurrentToolText','ProductionStopReasonText','ProductionQueueSummaryText','ProductionAlarmText','ProductionRecentResultsGrid','ProductionQueueRunScopeComboBox','ProductionQueueRunScopeComboBox2','DockXldProjectiveTransformPanel','DockXldProjectiveCoordinatePolicyComboBox')){Assert-True($null-ne(Field $name)) "$name is missing."}
foreach($index in 1..4){foreach($side in @('Source','Target')){foreach($axis in @('Row','Column')){Assert-True($null-ne(Field ("DockXldProjective{0}{1}{2}TextBox"-f$side,$axis,$index))) 'A projective point editor is missing.'}}}
Assert-True($null-ne($catalog|Where-Object{$_.Kind.ToString()-eq'XldProjectiveTransform'}|Select-Object -First 1)) 'XLD projective tool is missing from the toolbox.'
$projectiveKind=[Enum]::Parse($kindType,'XldProjectiveTransform');$inputs=$metadataType.GetMethod('GetInputPorts',$staticPublic).Invoke($null,[object[]]@($projectiveKind));$outputs=$metadataType.GetMethod('GetOutputPorts',$staticPublic).Invoke($null,[object[]]@($projectiveKind));Assert-True(($inputs|Where-Object{$_.PortName-eq'XLD'-and$_.DataType-eq'XLD'-and-not$_.IsOptional}).Count-eq1) 'Required typed XLD input is missing.'
foreach($port in @('XLD','ContourCount','InputTotalLength','TotalLength','MinRow','MinColumn','MaxRow','MaxColumn','HomMat2D','PointError','CoordinatePolicy','AttributePolicy','Parameters','ResultCode')){Assert-True(($outputs|Where-Object PortName -eq $port).Count-eq1) "Projective output $port is missing."}

$app=[Windows.Application]::Current;if($null-eq$app){$app=New-Object Windows.Application;$app.ShutdownMode=[Windows.ShutdownMode]::OnExplicitShutdown};$window.WindowStartupLocation=[Windows.WindowStartupLocation]::Manual;$window.Left=2;$window.Top=2;$window.Width=1760;$window.Height=980;$window.Topmost=$true;$window.Show();$window.Activate()|Out-Null;Pump-Ui 350

# A: the operator page must switch the same live workspace and must not create a second recipe/runtime/image/result state.
try{$loadQueue.Invoke($window,[object[]]@(,[string[]]@($imagePath)))|Out-Null} catch [Reflection.TargetInvocationException]{throw $_.Exception.InnerException}
$disposeFlow.Invoke($window,@())|Out-Null;$flow.Clear();$threshold=New-Tool ImageThreshold 'S42 Production Threshold';$threshold.Parameters.ImageThresholdMinGray=0;$threshold.Parameters.ImageThresholdMaxGray=255;$flow.Add($threshold)
(Field 'RecipeNameEditTextBox').Text='S42 真实生产方案';(Field 'FlowTimeoutTextBox').Text='0';(Field 'StopOnNgCheckBox').IsChecked=$false
$imagePanel=Field 'ImageWorkspacePanel';$originalImage=Field 'currentImage';$originalToolId=$threshold.ToolId;$originalFlowCount=$flow.Count
$setProduction.Invoke($window,[object[]]@($true))|Out-Null;Pump-Ui 150
Assert-True([bool](Field 'productionRunMode')) 'Production mode flag was not set.'
Assert-True((Field 'ProductionRunPanel').Visibility.ToString()-eq'Visible'-and(Field 'DeveloperToolbarPanel').Visibility.ToString()-eq'Collapsed'-and(Field 'ToolCatalogPanel').Visibility.ToString()-eq'Collapsed'-and(Field 'FlowWorkspacePanel').Visibility.ToString()-eq'Collapsed') 'Editing surfaces were not removed from the operator view.'
Assert-True((Field 'ImageWorkspaceToolbarPanel').Visibility.ToString()-eq'Collapsed') 'ROI/image editing toolbar remained active in production mode.'
Assert-True([Windows.Controls.Grid]::GetColumn($imagePanel)-eq0-and[Windows.Controls.Grid]::GetColumnSpan($imagePanel)-eq3-and[Windows.Controls.Grid]::GetRowSpan($imagePanel)-eq3) 'The real HALCON image workspace was not expanded in production mode.'
Assert-True([Object]::ReferenceEquals($originalImage,(Field 'currentImage'))-and(Field 'flowTools').Count-eq$originalFlowCount-and(Field 'flowTools')[0].ToolId-eq$originalToolId) 'Production mode created or replaced runtime state.'
$modeType=$assembly.GetType('HalconWinFormsDemo.Models.VmFlowRunRequestMode',$true);$fullMode=[Enum]::Parse($modeType,'Full');Wait-UiTask($runRange.Invoke($window,[object[]]@($fullMode,'S42 production operator'))) 30000
Assert-True((Field 'ProductionOverallResultText').Text-eq'OK'-and(Field 'ProductionRecentResultsGrid').Items.Count-gt0) 'Production page did not mirror the real flow result and result store.'
Assert-True((Field 'ProductionSchemeText').Text.Contains('S42 真实生产方案')) 'Production page did not mirror the current recipe name.'
$mainScope=Field 'ImageQueueRunScopeComboBox';$scope1=Field 'ProductionQueueRunScopeComboBox';$scope2=Field 'ProductionQueueRunScopeComboBox2';$scope2.SelectedIndex=2;Pump-Ui 80;Assert-True($mainScope.SelectedIndex-eq2-and$scope1.SelectedIndex-eq2) 'Production queue scope did not synchronize with the real queue executor.'
$mainType.GetMethod('AppendAlarm',$private).Invoke($window,[object[]]@('S42 可见报警'))|Out-Null;Pump-Ui 80;Assert-True((Field 'ProductionAlarmText').Text.Contains('S42 可见报警')) 'Production alarm card did not mirror the real alarm stream.'
Set-Private 'isFlowExecutionActive' $true;$setProduction.Invoke($window,[object[]]@($false))|Out-Null;Assert-True([bool](Field 'isFlowExecutionActive')) 'Returning to development reset live execution state.';Set-Private 'isFlowExecutionActive' $false
Assert-True((Field 'DeveloperToolbarPanel').Visibility.ToString()-eq'Visible'-and(Field 'ProductionRunPanel').Visibility.ToString()-eq'Collapsed'-and[Windows.Controls.Grid]::GetColumn($imagePanel)-eq4-and[Windows.Controls.Grid]::GetColumnSpan($imagePanel)-eq1) 'Development layout was not restored.'
$setProduction.Invoke($window,[object[]]@($true))|Out-Null;$setProduction.Invoke($window,[object[]]@($false))|Out-Null;Assert-True([Object]::ReferenceEquals($originalImage,(Field 'currentImage'))) 'Repeated mode switching changed the current image.'

# B: projective_trans_contour_xld, normalized DLT, coordinate policy, errors, lifecycle and downstream chain.
$direct=New-Tool XldProjectiveTransform 'S42 Direct Projective';$rectangle=New-RectangleContour
try{
    Invoke-Projective $direct $rectangle|Out-Null;Assert-True([Math]::Abs([double](Get-Out $direct MinRow))-lt.0001-and[Math]::Abs([double](Get-Out $direct MaxColumn)-80)-lt.0001) 'Identity projective transform changed contour bounds.';Assert-True([double](Get-Out $direct PointError)-lt.000001) 'Identity four-point error is too large.'
    $old=Get-Out $direct XLD;$direct.Parameters.XldProjectiveTargetRow1=3;$direct.Parameters.XldProjectiveTargetColumn1=8;$direct.Parameters.XldProjectiveTargetRow2=0;$direct.Parameters.XldProjectiveTargetColumn2=92;$direct.Parameters.XldProjectiveTargetRow3=52;$direct.Parameters.XldProjectiveTargetColumn3=76;$direct.Parameters.XldProjectiveTargetRow4=44;$direct.Parameters.XldProjectiveTargetColumn4=-6;Invoke-Projective $direct $rectangle|Out-Null;Assert-True($old.IsDisposed) 'Projective rerun did not dispose the prior managed XLD.';Assert-True([double](Get-Out $direct PointError)-lt.01-and([string](Get-Out $direct HomMat2D)).Split(',').Count-eq9) 'Trapezoid transform did not expose a valid 9-element matrix/error.'
    $standard=[string](Get-Out $direct HomMat2D);$direct.Parameters.XldProjectiveCoordinatePolicy='AffineTransPixel';Invoke-Projective $direct $rectangle|Out-Null;$raw=[string](Get-Out $direct HomMat2D);Assert-True($standard-ne$raw-and(Get-Out $direct CoordinatePolicy).Contains('affine_trans_pixel')) 'Coordinate policy did not produce the documented matrix distinction.';Assert-True((Get-Out $direct AttributePolicy).Contains('projective_trans_contour_xld')) 'HALCON attribute policy is not explicit.'
    [HalconDotNet.HTuple]$callerCount=$null;[HalconDotNet.HOperatorSet]::CountObj($rectangle,[ref]$callerCount);Assert-True($callerCount.I-eq1) 'Caller-owned XLD was mutated or disposed.'
}finally{$rectangle.Dispose();$direct.Dispose()}
$open=New-OpenContour;$closed=New-RectangleContour;[HalconDotNet.HObject]$multi=$null;$multiTool=New-Tool XldProjectiveTransform 'S42 Multiple';try{[HalconDotNet.HOperatorSet]::ConcatObj($open,$closed,[ref]$multi);Invoke-Projective $multiTool $multi|Out-Null;Assert-True([int](Get-Out $multiTool ContourCount)-eq2) 'Open/closed multi-contour collection was not preserved.'}finally{$open.Dispose();$closed.Dispose();if($null-ne$multi){$multi.Dispose()};$multiTool.Dispose()}
[HalconDotNet.HObject]$empty=$null;[HalconDotNet.HOperatorSet]::GenEmptyObj([ref]$empty);$emptyTool=New-Tool XldProjectiveTransform 'S42 Empty';try{$record=Invoke-Projective $emptyTool $empty;Assert-True($record.ResultCode-eq'NG'-and[int](Get-Out $emptyTool ContourCount)-eq0) 'Empty XLD projective semantics are wrong.'}finally{$empty.Dispose();$emptyTool.Dispose()}
foreach($case in @('Duplicate','Crossed','Collinear','Policy')){$tool=New-Tool XldProjectiveTransform ('S42 Invalid '+$case);$input=New-OpenContour;try{if($case-eq'Duplicate'){$tool.Parameters.XldProjectiveSourceRow2=0;$tool.Parameters.XldProjectiveSourceColumn2=0}elseif($case-eq'Crossed'){$tool.Parameters.XldProjectiveSourceRow2=479;$tool.Parameters.XldProjectiveSourceColumn2=639;$tool.Parameters.XldProjectiveSourceRow3=0;$tool.Parameters.XldProjectiveSourceColumn3=639}elseif($case-eq'Collinear'){$tool.Parameters.XldProjectiveTargetRow1=0;$tool.Parameters.XldProjectiveTargetRow2=0;$tool.Parameters.XldProjectiveTargetRow3=0;$tool.Parameters.XldProjectiveTargetRow4=0}else{$tool.Parameters.XldProjectiveCoordinatePolicy='Bogus'};$rejected=$false;try{Invoke-Projective $tool $input|Out-Null}catch{$rejected=$true};Assert-True $rejected "Invalid projective case $case was accepted."}finally{$input.Dispose();$tool.Dispose()}}

$disposeFlow.Invoke($window,@())|Out-Null;$flow.Clear();$producer=New-Tool SubpixelEdgeExtraction 'S42 XLD Producer';$projective=New-Tool XldProjectiveTransform 'S42 Flow Projective';$fit=New-Tool XldLineFitting 'S42 Fit';$judge=New-Tool NumericJudge 'S42 Count Judge';$projective.SetInputBinding('XLD',$producer.ToolId,'XLD');$fit.SetInputBinding('XLD',$projective.ToolId,'XLD');$judge.SetInputBinding('Value',$projective.ToolId,'ContourCount');$judge.InputToolId=$projective.ToolId;$judge.InputPortName='ContourCount';$judge.NumericLowerLimit=1;$judge.NumericUpperLimit=1;foreach($tool in @($producer,$projective,$fit,$judge)){$flow.Add($tool)}
$flowXld=New-OpenContour;try{$producer.SetOutputValue('XLD',(New-Snapshot $flowXld $producer));$producer.SetOutputValue('ContourCount',[double]1);$producer.ResultCode='OK'}finally{$flowXld.Dispose()};Invoke-Execute $projective 'S42 flow'|Out-Null;Invoke-Execute $fit 'S42 flow'|Out-Null;Invoke-Execute $judge 'S42 flow'|Out-Null;Assert-True($projective.ResultCode-eq'OK'-and$fit.ResultCode-eq'OK'-and$judge.ResultCode-eq'OK') 'Projective XLD/ContourCount did not drive fitting and NumericJudge.'
(Field 'FlowToolList').SelectedItem=$projective;$mainType.GetMethod('LoadDockConfigurationDraft',$private).Invoke($window,[object[]]@($projective))|Out-Null;Assert-True((Field 'DockXldProjectiveTransformPanel').Visibility.ToString()-eq'Visible'-and(Field 'DockXldProjectiveSourceColumn2TextBox').Text-eq'639') 'Projective dock panel is not visible/synchronized.'
$recipe=$captureRecipe.Invoke($window,@());$saved=$recipe.ToolFlow|Where-Object ToolType -eq 'XldProjectiveTransform'|Select-Object -First 1;Assert-True($saved.Parameters.XldProjectiveSourceColumn2-eq639-and$saved.Parameters.XldProjectiveCoordinatePolicy-eq'StandardPixelCenter') 'Projective parameters were not captured in recipe.'
$parameterType=$assembly.GetType('HalconWinFormsDemo.Models.VmToolParameterData',$true);$legacy=$parameterType.GetConstructor([Type[]]@()).Invoke(@());$legacy.XldProjectiveSourceRow1=0;$legacy.XldProjectiveSourceColumn1=0;$legacy.XldProjectiveSourceRow2=0;$legacy.XldProjectiveSourceColumn2=0;$legacy.XldProjectiveSourceRow3=0;$legacy.XldProjectiveSourceColumn3=0;$legacy.XldProjectiveSourceRow4=0;$legacy.XldProjectiveSourceColumn4=0;$legacy.XldProjectiveTargetRow1=0;$legacy.XldProjectiveTargetColumn1=0;$legacy.XldProjectiveTargetRow2=0;$legacy.XldProjectiveTargetColumn2=0;$legacy.XldProjectiveTargetRow3=0;$legacy.XldProjectiveTargetColumn3=0;$legacy.XldProjectiveTargetRow4=0;$legacy.XldProjectiveTargetColumn4=0;$legacy.XldProjectiveCoordinatePolicy=$null;$legacy.Normalize();Assert-True($legacy.XldProjectiveSourceColumn2-eq639-and$legacy.XldProjectiveTargetRow3-eq479-and$legacy.XldProjectiveCoordinatePolicy-eq'StandardPixelCenter') 'Missing projective fields do not normalize to safe identity defaults.'
$upstream=Get-Out $producer XLD;$upstream.Dispose();$rejected=$false;try{Invoke-Execute $projective 'S42 disposed upstream'|Out-Null}catch{$rejected=$true};Assert-True $rejected 'Disposed upstream XLD was not rejected.'

$mainType.GetField('recipeCloseConfirmed',$private).SetValue($window,$true);$window.Close();$app.Shutdown();if(Test-Path $tempRoot){Remove-Item -LiteralPath $tempRoot -Recurse -Force}
Write-Output 'S42 production run page and HALCON XLD projective transform smoke tests passed.'
